"""JSON Lines import and export for ledger records."""

import json

from ledgerfmt.model import record_from_wire, record_to_wire


_FIELDS = {"account", "amount", "tags"}


def load(stream):
    """Read one JSON object per nonblank line into ledger records."""
    records = []
    for line_number, line in enumerate(stream, start=1):
        if not line.strip():
            continue
        try:
            value = json.loads(line)
        except (json.JSONDecodeError, RecursionError, TypeError, ValueError) as exc:
            raise ValueError(f"JSONL line {line_number}: invalid JSON: {exc}") from exc

        if not isinstance(value, dict):
            raise ValueError(f"JSONL line {line_number}: expected a JSON object")
        if set(value) != _FIELDS:
            raise ValueError(
                f"JSONL line {line_number}: expected exactly account, amount, and tags fields"
            )
        try:
            record = record_from_wire(value["account"], value["amount"], value["tags"])
        except (ValueError, TypeError, KeyError) as exc:
            raise ValueError(f"JSONL line {line_number}: invalid record: {exc}") from exc
        records.append(record)
    return records


def dump(records, stream):
    """Write records as JSON Lines, validating all records before writing."""
    lines = []
    for row_number, record in enumerate(records, start=1):
        try:
            wire = record_to_wire(record)
            line = json.dumps(wire, ensure_ascii=False, sort_keys=True)
        except (ValueError, TypeError, KeyError, AttributeError) as exc:
            raise ValueError(f"JSONL row {row_number}: invalid record: {exc}") from exc
        lines.append(line)

    if lines:
        stream.write("\n".join(lines) + "\n")

