"""CSV ledger format with a JSON-encoded tags column."""

import csv as _csv
import io
import json

from ledgerfmt.model import record_from_wire, record_to_wire


_HEADER = ["account", "amount", "tags"]


def load(stream):
    """Load ledger records from a CSV text stream."""
    reader = _csv.reader(stream, strict=True)
    records = []

    try:
        try:
            header = next(reader)
        except StopIteration:
            raise ValueError("row 1 (line 1): missing CSV header") from None
        except _csv.Error as error:
            raise ValueError(f"row 1 (line {reader.line_num or 1}): malformed CSV header: {error}") from None

        if header != _HEADER:
            raise ValueError(
                f"row 1 (line {reader.line_num}): expected header account,amount,tags"
            )

        logical_row = 1
        while True:
            try:
                row = next(reader)
            except StopIteration:
                break
            except _csv.Error as error:
                raise ValueError(
                    f"row {logical_row + 1} (line {reader.line_num}): malformed CSV: {error}"
                ) from None

            logical_row += 1
            context = f"row {logical_row} (line {reader.line_num})"
            if not row:
                raise ValueError(f"{context}: blank records are not allowed")
            if len(row) != 3:
                raise ValueError(f"{context}: expected exactly 3 fields, found {len(row)}")

            account, amount, encoded_tags = row
            try:
                tags = json.loads(encoded_tags)
            except (json.JSONDecodeError, TypeError) as error:
                raise ValueError(f"{context}: invalid tags JSON: {error}") from None
            try:
                records.append(record_from_wire(account, amount, tags))
            except (ValueError, TypeError, KeyError) as error:
                raise ValueError(f"{context}: invalid ledger record: {error}") from None
    except OSError:
        raise

    return records


def dump(records, stream):
    """Write records as CSV, validating every record before touching stream."""
    staged = io.StringIO(newline="")
    writer = _csv.writer(staged, lineterminator="\n", quoting=_csv.QUOTE_MINIMAL)
    writer.writerow(_HEADER)

    for row_number, record in enumerate(records, start=2):
        try:
            wire = record_to_wire(record)
            tags = json.dumps(wire["tags"], ensure_ascii=False)
            writer.writerow([wire["account"], wire["amount"], tags])
        except (ValueError, TypeError, KeyError, AttributeError) as error:
            raise ValueError(f"row {row_number}: invalid ledger record: {error}") from None

    stream.write(staged.getvalue())
